{
  "name": "VXI-11仪器通信客户端",
  "name_en": "VXI-11 Instrument Communication Client",
  "manufacturer": "",
  "description": "用于通过 VXI-11/RPC 协议与网络实验仪器建立连接并交换数据的非物理软件组件。它提供原始读写、状态字读取、触发、清除、远程/本地切换、锁定控制，以及底层链路创建、打包与解包等通用通信功能，适合在实验自动化中连接支持 VXI-11 的仪器。",
  "description_en": "A non-physical software component for connecting to and exchanging data with networked laboratory instruments via the VXI-11/RPC protocol. It provides raw read/write, status-byte reading, trigger, clear, remote/local switching, lock control, and low-level link creation plus packet packing/unpacking for automation workflows with VXI-11-capable instruments.",
  "tag_hints": [
    "VXI-11",
    "RPC instrument control",
    "LAN instrument communication",
    "SCPI over Ethernet",
    "status byte polling",
    "remote/local lock control"
  ],
  "actions": [
    {
      "action_name": "auto-clear",
      "description": "向仪器发送清除命令。",
      "description_en": "Send a clear command to the instrument."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭与 VXI-11 仪器的连接。",
      "description_en": "Close the connection to the VXI-11 instrument."
    },
    {
      "action_name": "auto-initialize",
      "description": "打开与 VXI-11 仪器的连接。",
      "description_en": "Open a connection to the VXI-11 instrument."
    },
    {
      "action_name": "auto-local",
      "description": "向仪器发送本地控制命令。",
      "description_en": "Send a local-control command to the instrument."
    },
    {
      "action_name": "auto-lock",
      "description": "向仪器发送锁定命令。",
      "description_en": "Send a lock command to the instrument."
    },
    {
      "action_name": "auto-read_raw",
      "description": "从仪器读取原始二进制数据。",
      "description_en": "Read raw binary data from the instrument."
    },
    {
      "action_name": "auto-read_stb",
      "description": "读取仪器状态字节。",
      "description_en": "Read the instrument status byte."
    },
    {
      "action_name": "auto-remote",
      "description": "向仪器发送远程控制命令。",
      "description_en": "Send a remote-control command to the instrument."
    },
    {
      "action_name": "auto-trigger",
      "description": "向仪器发送触发命令。",
      "description_en": "Send a trigger command to the instrument."
    },
    {
      "action_name": "auto-unlock",
      "description": "向仪器发送解锁命令。",
      "description_en": "Send an unlock command to the instrument."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向仪器写入原始二进制数据。",
      "description_en": "Write raw binary data to the instrument."
    },
    {
      "action_name": "auto-pack_device_link",
      "description": "打包设备链路标识数据。",
      "description_en": "Pack device link identifier data."
    },
    {
      "action_name": "auto-pack_create_link_parms",
      "description": "打包创建链路请求参数。",
      "description_en": "Pack parameters for a create-link request."
    },
    {
      "action_name": "auto-pack_device_write_parms",
      "description": "打包设备写入请求参数。",
      "description_en": "Pack parameters for a device write request."
    },
    {
      "action_name": "auto-pack_device_read_parms",
      "description": "打包设备读取请求参数。",
      "description_en": "Pack parameters for a device read request."
    },
    {
      "action_name": "auto-pack_device_generic_parms",
      "description": "打包通用设备请求参数。",
      "description_en": "Pack generic device request parameters."
    },
    {
      "action_name": "auto-pack_device_remote_func_parms",
      "description": "打包设备远程功能请求参数。",
      "description_en": "Pack parameters for a device remote-function request."
    },
    {
      "action_name": "auto-pack_device_enable_srq_parms",
      "description": "打包启用 SRQ 的请求参数。",
      "description_en": "Pack parameters for enabling SRQ."
    },
    {
      "action_name": "auto-pack_device_lock_parms",
      "description": "打包设备锁定请求参数。",
      "description_en": "Pack parameters for a device lock request."
    },
    {
      "action_name": "auto-pack_device_docmd_parms",
      "description": "打包设备通用命令请求参数。",
      "description_en": "Pack parameters for a generic device command request."
    },
    {
      "action_name": "auto-unpack_device_link",
      "description": "解包设备链路标识数据。",
      "description_en": "Unpack device link identifier data."
    },
    {
      "action_name": "auto-unpack_device_error",
      "description": "解包设备错误信息。",
      "description_en": "Unpack device error information."
    },
    {
      "action_name": "auto-unpack_create_link_resp",
      "description": "解包创建链路响应。",
      "description_en": "Unpack a create-link response."
    },
    {
      "action_name": "auto-unpack_device_write_resp",
      "description": "解包设备写入响应。",
      "description_en": "Unpack a device write response."
    },
    {
      "action_name": "auto-unpack_device_read_resp",
      "description": "解包设备读取响应。",
      "description_en": "Unpack a device read response."
    },
    {
      "action_name": "auto-unpack_device_read_stb_resp",
      "description": "解包状态字节读取响应。",
      "description_en": "Unpack a status-byte read response."
    },
    {
      "action_name": "auto-unpack_device_docmd_resp",
      "description": "解包设备通用命令响应。",
      "description_en": "Unpack a generic device command response."
    },
    {
      "action_name": "auto-create_link",
      "description": "创建到 VXI-11 设备的通信链路。",
      "description_en": "Create a communication link to a VXI-11 device."
    },
    {
      "action_name": "auto-device_write",
      "description": "执行 VXI-11 设备写入操作。",
      "description_en": "Perform a VXI-11 device write operation."
    },
    {
      "action_name": "auto-device_read",
      "description": "执行 VXI-11 设备读取操作。",
      "description_en": "Perform a VXI-11 device read operation."
    },
    {
      "action_name": "auto-device_read_stb",
      "description": "执行 VXI-11 状态字节读取操作。",
      "description_en": "Perform a VXI-11 status-byte read operation."
    },
    {
      "action_name": "auto-device_trigger",
      "description": "执行 VXI-11 设备触发操作。",
      "description_en": "Perform a VXI-11 device trigger operation."
    },
    {
      "action_name": "auto-device_clear",
      "description": "执行 VXI-11 设备清除操作。",
      "description_en": "Perform a VXI-11 device clear operation."
    },
    {
      "action_name": "auto-device_remote",
      "description": "执行 VXI-11 设备远程控制切换。",
      "description_en": "Perform a VXI-11 device remote-control operation."
    },
    {
      "action_name": "auto-device_local",
      "description": "执行 VXI-11 设备本地控制切换。",
      "description_en": "Perform a VXI-11 device local-control operation."
    },
    {
      "action_name": "auto-device_lock",
      "description": "执行 VXI-11 设备锁定操作。",
      "description_en": "Perform a VXI-11 device lock operation."
    },
    {
      "action_name": "auto-device_unlock",
      "description": "执行 VXI-11 设备解锁操作。",
      "description_en": "Perform a VXI-11 device unlock operation."
    },
    {
      "action_name": "auto-device_enable_srq",
      "description": "启用设备 SRQ 服务请求功能。",
      "description_en": "Enable device SRQ service requests."
    },
    {
      "action_name": "auto-device_docmd",
      "description": "执行设备通用命令操作。",
      "description_en": "Perform a generic device command operation."
    },
    {
      "action_name": "auto-destroy_link",
      "description": "销毁与设备的通信链路。",
      "description_en": "Destroy the communication link to the device."
    },
    {
      "action_name": "auto-create_intr_chan",
      "description": "创建中断通信通道。",
      "description_en": "Create an interrupt communication channel."
    },
    {
      "action_name": "auto-destroy_intr_chan",
      "description": "销毁中断通信通道。",
      "description_en": "Destroy an interrupt communication channel."
    }
  ]
}

